var a=77;var i=[{id:`cooking-077-01`,theoryId:77,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why does spacing vegetables on a roasting tray improve browning?`,ua:`Чому відстань між овочами на деку покращує підрум’янення?`},explanation:{en:`Airflow and evaporation support a drier, hotter surface.`,ua:`Циркуляція повітря й випаровування допомагають поверхні стати сухішою та гарячішою.`},options:[{id:`a`,text:{en:`Moisture can escape instead of pooling between pieces`,ua:`Волога може випаровуватися, а не накопичуватися між шматочками`}},{id:`b`,text:{en:`The tray produces extra salt`,ua:`Деко виробляє додаткову сіль`}},{id:`c`,text:{en:`The oven no longer needs heat`,ua:`Духовці більше не потрібен нагрів`}}],answer:{optionIds:[`a`]}},{id:`cooking-077-02`,theoryId:77,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`The same oven setting guarantees identical results in every oven.`,ua:`Однакове налаштування температури гарантує однаковий результат у будь-якій духовці.`},explanation:{en:`Calibration, airflow, tray material and loading differ between ovens.`,ua:`Калібрування, циркуляція, матеріал дека й завантаження відрізняються.`},answer:{value:!1}},{id:`cooking-077-03`,theoryId:77,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match roasting controls to their effects.`,ua:`Поєднайте параметри запікання з їхнім впливом.`},explanation:{en:`Roasting is influenced by geometry and equipment, not temperature setting alone.`,ua:`Запікання залежить від форми продукту й обладнання, а не лише від температури.`},leftItems:[{id:`l1`,text:{en:`Convection fan`,ua:`Конвекційний вентилятор`}},{id:`l2`,text:{en:`Crowded tray`,ua:`Переповнене деко`}},{id:`l3`,text:{en:`Thick ceramic dish`,ua:`Товста керамічна форма`}}],rightItems:[{id:`r3`,text:{en:`Changes heating and thermal response`,ua:`Змінює швидкість нагрівання та теплову інерцію`}},{id:`r2`,text:{en:`Holds moisture between pieces`,ua:`Затримує вологу між шматочками`}},{id:`r1`,text:{en:`Increases air movement around food`,ua:`Посилює рух повітря навколо їжі`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-077-04`,theoryId:77,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Roasted carrots are pale and wet. What change is most helpful?`,ua:`Запечена морква бліда й мокра. Яка зміна найкраща?`},explanation:{en:`Evaporation and direct heat support surface browning.`,ua:`Випаровування й безпосередній нагрів сприяють підрум’яненню.`},options:[{id:`a`,text:{en:`Spread pieces out and continue roasting appropriately`,ua:`Розкласти шматочки вільніше та продовжити належне запікання`}},{id:`b`,text:{en:`Cover tightly with foil for the entire remaining time`,ua:`Щільно накрити фольгою на весь час`}},{id:`c`,text:{en:`Pour cold water over the tray`,ua:`Залити деко холодною водою`}}],answer:{optionIds:[`a`]}},{id:`cooking-077-05`,theoryId:77,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which statement about roasting meat is incorrect?`,ua:`Яке твердження про запікання м’яса неправильне?`},explanation:{en:`Internal temperature must be checked directly when food safety depends on it.`,ua:`Коли від внутрішньої температури залежить безпека, її слід вимірювати напряму.`},options:[{id:`a`,text:{en:`Roast size affects internal heating time`,ua:`Розмір печені впливає на час нагрівання всередині`}},{id:`b`,text:{en:`A food thermometer is useful for checking doneness`,ua:`Термометр корисний для перевірки готовності`}},{id:`c`,text:{en:`A browned exterior always proves safe internal temperature`,ua:`Рум’яна зовнішня поверхня завжди доводить безпечність середини`}}],answer:{optionIds:[`c`]}},{id:`cooking-077-06`,theoryId:77,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which variables affect oven-roasted vegetable color?`,ua:`Які чинники впливають на колір запечених овочів?`},explanation:{en:`Browning depends on real heating and evaporation conditions.`,ua:`Підрум’янення залежить від фактичного нагріву й випаровування.`},options:[{id:`a`,text:{en:`Surface moisture`,ua:`Волога поверхні`}},{id:`b`,text:{en:`Tray crowding`,ua:`Щільність викладання на деку`}},{id:`c`,text:{en:`Oven airflow and actual temperature`,ua:`Циркуляція повітря та фактична температура духовки`}},{id:`d`,text:{en:`Only the printed recipe title`,ua:`Лише назва рецепта`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:77,exercises:i};export{n as default,i as exercises,a as theoryId};